const $=id=>document.getElementById(id);
const busSvg='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="5" y="3" width="14" height="17" rx="3"/><path d="M5 12h14M8 7h8M8 20v2m8-2v2"/><circle cx="8.5" cy="16" r=".8"/><circle cx="15.5" cy="16" r=".8"/></svg>';
let center=[12.9784,77.6408],selected='500D',filter='all',radius=2,map,markers=[],userMarker,lastUpdated=Date.now();
const buses=[{id:'500D',type:'AC',passengers:24,capacity:50,from:'Hebbal',to:'Central Silk Board',offset:[.0044,.0035]},{id:'201R',type:'Non-AC',passengers:38,capacity:50,from:'Srinagar',to:'CV Raman Nagar',offset:[-.0048,-.004]},{id:'335E',type:'AC',passengers:12,capacity:45,from:'Majestic',to:'Whitefield',offset:[.008,-.0074]},{id:'100',type:'Non-AC',passengers:47,capacity:50,from:'Majestic',to:'Jeevan Bima Nagar',offset:[-.003,.011]},{id:'314B',type:'Non-AC',passengers:18,capacity:50,from:'Shivajinagar',to:'CV Raman Nagar',offset:[-.010,.003]},{id:'V-500K',type:'AC',passengers:32,capacity:45,from:'ITPL',to:'Banashankari',offset:[.0085,.011]}];
function occupancy(b){let p=b.passengers/b.capacity;return p<.6?{label:'Plenty of room',color:'#4a967d'}:p<.85?{label:'Filling up',color:'#b28b3e'}:{label:'Almost full',color:'#c7796c'}}
function coords(b){return [center[0]+b.offset[0],center[1]+b.offset[1]]}function distance(b){return Math.hypot(b.offset[0]*111,b.offset[1]*111*Math.cos(center[0]*Math.PI/180))}function visible(){return buses.filter(b=>(filter==='all'||b.type===filter)&&distance(b)<=radius).sort((a,b)=>distance(a)-distance(b))}
function notify(message){$('status').textContent=message;$('status').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('status').hidden=true,6000)}
function render(){const shown=visible();if(!shown.some(b=>b.id===selected))selected=shown[0]?.id;$('map-count').textContent=shown.length+' buses';$('list-count').textContent=shown.length;$('bus-list').innerHTML=shown.length?shown.map(b=>{const o=occupancy(b);return `<button class="bus-card ${selected===b.id?'chosen':''}" style="--tone:${o.color}" data-bus="${b.id}" aria-pressed="${selected===b.id}" aria-label="Bus ${b.id}, ${b.passengers} of ${b.capacity} passengers"><div class="card-top"><div><strong>${b.id}</strong><span class="type">${b.type==='AC'?'❄ AC':'Non-AC'}</span></div><span class="card-distance">${distance(b).toFixed(1)} km away</span></div><p class="card-route">${b.from} → ${b.to}</p><div class="card-bottom"><span class="card-count">${b.passengers}<small> / ${b.capacity} passengers</small></span><span class="card-status">${o.label}</span></div><div class="bar"><span style="width:${b.passengers/b.capacity*100}%"></span></div></button>`}).join(''):'<p class="empty">No sample buses in this range. Try a larger radius or a different filter.</p>';
document.querySelectorAll('[data-bus]').forEach(el=>el.onclick=()=>selectBus(el.dataset.bus));renderDetail();renderMarkers()}
function renderDetail(){const b=buses.find(b=>b.id===selected);if(!b){$('detail').innerHTML='<h2>No buses selected</h2><p>Adjust your filters to explore more buses.</p>';return}const o=occupancy(b);$('detail').innerHTML=`<div class="detail-top"><span>BUS IN FOCUS</span><span>● SAMPLE DATA</span></div><div class="bus-title"><span class="bus-icon">${busSvg}</span><h3>${b.id}</h3><span class="type">${b.type==='AC'?'❄ AC':'Non-AC'}</span></div><div class="route">${b.from} <span>→</span> ${b.to}</div><div class="occupancy" style="--tone:${o.color}"><span class="occupancy-label">PASSENGERS ON BOARD</span><div class="big-count"><strong>${b.passengers}</strong><span>/ ${b.capacity}</span></div><div class="bar" role="meter" aria-label="Passenger occupancy" aria-valuenow="${b.passengers}" aria-valuemin="0" aria-valuemax="${b.capacity}"><span style="width:${b.passengers/b.capacity*100}%"></span></div><div class="occ-bottom"><span>● ${o.label}</span><span>${Math.round(b.passengers/b.capacity*100)}% occupied</span></div></div><div class="detail-facts"><div><small>Available capacity</small><strong>${b.capacity-b.passengers} passengers</strong></div><div><small>Maximum capacity</small><strong>${b.capacity} passengers</strong></div></div><p class="detail-hint">⌖ ${distance(b).toFixed(1)} km from ${userMarker?'your location':'sample location'} · ${b.type==='AC'?'Air conditioned':'Non-air conditioned'}</p>`}
function renderMarkers(){if(!map)return;markers.forEach(m=>m.remove());markers=[];visible().forEach(b=>{const o=occupancy(b);let m=L.marker(coords(b),{title:`Bus ${b.id}: ${b.passengers} of ${b.capacity} passengers`,icon:L.divIcon({className:'bus-pin',html:`<div class="pin ${selected===b.id?'selected':''}" style="--tone:${o.color}"><span class="pin-label">${b.id}</span>${busSvg}<b>${b.passengers}</b></div>`,iconSize:[70,42],iconAnchor:[35,42]})}).addTo(map).on('click',()=>selectBus(b.id));markers.push(m)})}
function selectBus(id){selected=id;render();const b=buses.find(b=>b.id===id);if(map)map.panTo(coords(b));}
if(window.L){map=L.map('map',{zoomControl:false,scrollWheelZoom:false}).setView(center,14);L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> &copy; <a href="https://carto.com/attributions">CARTO</a>',maxZoom:19}).addTo(map).on('tileerror',()=>notify('Map tiles could not load. Bus details are still available below.'));L.control.zoom({position:'topright'}).addTo(map);L.circleMarker(center,{radius:7,color:'white',weight:3,fillColor:'#5488b5',fillOpacity:1}).addTo(map).bindTooltip('Sample location');}else{$('map').innerHTML='<p class="empty">The map could not load. Check your connection and reload. You can still explore the bus cards below.</p>'}
document.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>{filter=el.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===el));render()});$('radius').onchange=e=>{radius=Number(e.target.value);render();if(map)map.setView(center,radius===2?14:radius===1?15:16)};$('recenter').onclick=()=>map?.setView(center,14);
$('refresh').onclick=async()=>{$('refresh').disabled=true;$('refresh').innerHTML='<span>↻</span> Refreshing…';await new Promise(r=>setTimeout(r,700));buses.forEach(b=>{b.passengers=Math.max(0,Math.min(b.capacity,b.passengers+Math.floor(Math.random()*9)-4))});lastUpdated=Date.now();render();$('updated').textContent='Sample data · just updated';$('refresh').innerHTML='<span>↻</span> Refresh buses';$('refresh').disabled=false;notify('Sample passenger counts refreshed. A live transit feed is not connected.')};
$('locate').onclick=()=>{if(!navigator.geolocation){notify('Location is unavailable in this browser. Showing the sample location.');return}$('locate').disabled=true;notify('Waiting for location permission…');navigator.geolocation.getCurrentPosition(pos=>{center=[pos.coords.latitude,pos.coords.longitude];$('location-label').textContent='Your current location';if(map){if(userMarker)userMarker.remove();userMarker=L.marker(center,{icon:L.divIcon({className:'you-dot',iconSize:[19,19],iconAnchor:[9,9]})}).addTo(map).bindTooltip('You are here');map.setView(center,14)}render();$('locate').disabled=false;notify('Map centered on you. Bus positions and passenger counts are simulated.');},err=>{$('locate').disabled=false;notify(err.code===1?'Location permission denied. Allow location in your browser to try again.':'Could not find your location. Showing the sample location.');},{enableHighAccuracy:true,timeout:12000,maximumAge:30000})};
setInterval(()=>{const s=Math.floor((Date.now()-lastUpdated)/1000);$('updated').textContent=`Sample data · updated ${s<60?s+'s':Math.floor(s/60)+'m'} ago`},10000);render();
